// SPDX-License-Identifier: BSD-2-Clause-Patent
//
// Host scenarios for the real verified-window read path and runVerify.
//
// The adapter is compiled with GTA4L_EMMC_BLOCK_HOST_VERIFY=1 and a
// throwaway signed policy header generated by
// scripts/build-gta4l-verify-fixtures.py. The fixture image is served
// through the host IOMedia seam; the owner transport is replaced by a
// bounded read hook so the verified read path runs unmodified.
#include "Gta4lEmmcBlockTestSupport.h"

#define private public
#include "../../package/Gta4lEmmcBlock.cpp"
#undef private

#include <ctime>
#include <fstream>
#include <string>
#include <vector>

struct fixture {
	std::string image_path;
	std::vector<uint8_t> original;
	std::vector<uint8_t> image;
	uint64_t os_offset;
	uint64_t os_size;
	uint64_t os_table_offset;
	uint32_t os_table_bytes;
	uint64_t systemos_offset;
	uint64_t systemos_size;
	uint64_t systemos_table_offset;
	uint32_t systemos_table_bytes;
};

struct completion_record {
	int calls;
	IOReturn status;
	IOByteCount actual;
};

static fixture g_fixture;
static Gta4lEmmcBlock *g_self;
static IOMedia *g_userdata;
static Gta4lEmmcBlock *g_window_os;
static Gta4lEmmcBlock *g_window_systemos;
static struct gta4l_emmc_block_manifest g_manifest;
static uint32_t g_media_calls;
static uint32_t g_media_fail_at;
static uint32_t g_media_short_at;
static uint32_t g_owner_calls;
static uint32_t g_owner_fail_at;
static uint32_t g_owner_short_at;
static int g_owner_skip_completion;
static completion_record g_completion;

#define CHECK(condition) \
	do { \
		if (!(condition)) { \
			printf("  check failed: %s\n", #condition); \
			printf("  panic: %s\n", gta4l_test.panic); \
			return 1; \
		} \
	} while (0)

static void
completion_action(void *target, void *parameter, IOReturn status,
    IOByteCount actual)
{
	completion_record *record = static_cast<completion_record *>(target);

	(void)parameter;
	if (record != nullptr) {
		record->calls++;
		record->status = status;
		record->actual = actual;
	}
}

static IOReturn
fixture_media_read(IOMedia *media, UInt64 byteStart,
    IOMemoryDescriptor *buffer, UInt64 *actualByteCount)
{
	uint32_t length = (uint32_t)buffer->getLength();

	(void)media;
	g_media_calls++;
	if ((g_media_fail_at != 0u) && (g_media_calls == g_media_fail_at)) {
		if (actualByteCount != nullptr) {
			*actualByteCount = 0;
		}
		return kIOReturnIOError;
	}
	if ((byteStart + length) > g_fixture.image.size()) {
		return kIOReturnBadArgument;
	}
	if ((g_media_short_at != 0u) && (g_media_calls == g_media_short_at)) {
		buffer->writeBytes(0, g_fixture.image.data() + byteStart,
		    length - 1u);
		if (actualByteCount != nullptr) {
			*actualByteCount = length - 1u;
		}
		return kIOReturnSuccess;
	}
	buffer->writeBytes(0, g_fixture.image.data() + byteStart, length);
	if (actualByteCount != nullptr) {
		*actualByteCount = length;
	}
	return kIOReturnSuccess;
}

static IOReturn
fixture_owner_read(IOService *owner, IOMemoryDescriptor *buffer,
    UInt64 blockNumber, UInt64 nblks, IOStorageCompletion *completion)
{
	uint64_t offset = blockNumber * GTA4L_EMMC_BLOCK_BYTES;
	uint64_t bytes = nblks * GTA4L_EMMC_BLOCK_BYTES;

	(void)owner;
	g_owner_calls++;
	if ((g_owner_fail_at != 0u) && (g_owner_calls == g_owner_fail_at)) {
		if (completion != nullptr) {
			completion->action(completion->target,
			    completion->parameter, kIOReturnIOError, 0);
		}
		return kIOReturnSuccess;
	}
	if ((g_owner_short_at != 0u) && (g_owner_calls == g_owner_short_at)) {
		if (completion != nullptr) {
			completion->action(completion->target,
			    completion->parameter, kIOReturnSuccess,
			    (IOByteCount)(bytes - 1u));
		}
		return kIOReturnSuccess;
	}
	if (g_owner_skip_completion != 0) {
		return kIOReturnSuccess;
	}
	if ((offset + bytes) > g_fixture.image.size()) {
		if (completion != nullptr) {
			completion->action(completion->target,
			    completion->parameter, kIOReturnBadArgument, 0);
		}
		return kIOReturnSuccess;
	}
	buffer->writeBytes(0, g_fixture.image.data() + offset, bytes);
	if (completion != nullptr) {
		completion->action(completion->target, completion->parameter,
		    kIOReturnSuccess, bytes);
	}
	return kIOReturnSuccess;
}

static void
reset_hooks(void)
{
	g_media_calls = 0;
	g_media_fail_at = 0;
	g_media_short_at = 0;
	g_owner_calls = 0;
	g_owner_fail_at = 0;
	g_owner_short_at = 0;
	g_owner_skip_completion = 0;
	memset(&g_completion, 0, sizeof(g_completion));
	gta4l_test_media_read_hook = fixture_media_read;
	gta4l_test_owner_read_hook = fixture_owner_read;
}

static void
verify_multi_hook(uint32_t call)
{
	(void)call;
	gta4l_test.now_ms += 1u;
}

static int
begin(const char *arguments)
{
	gta4l_test_reset();
	gta4l_verified_reset();
	if (!g_fixture.original.empty()) {
		g_fixture.image = g_fixture.original;
	}
	gta4l_test.speed_active = 1;
	gta4l_test_multi_hook = verify_multi_hook;
	gta4l_test.boot_args = arguments;
	g_self = new Gta4lEmmcBlock();
	if (setjmp(gta4l_test.panic_jump) == 0) {
		if (!g_self->start(nullptr)) {
			printf("  start failed: %s\n", gta4l_test.panic);
			return 1;
		}
		return 0;
	}
	printf("  start panicked: %s\n", gta4l_test.panic);
	return 1;
}

static int
load_image(const char *path)
{
	std::ifstream stream(path, std::ios::binary);
	std::vector<uint8_t> data;

	if (!stream) {
		printf("  cannot open %s\n", path);
		return 1;
	}
	data.assign(std::istreambuf_iterator<char>(stream),
	    std::istreambuf_iterator<char>());
	if (data.empty()) {
		return 1;
	}
	g_fixture.original = data;
	g_fixture.image = data;
	return 0;
}

static int
attach_userdata(void)
{
	g_userdata = new IOMedia();
	g_userdata->whole_value = true;
	g_userdata->base_value = 0;
	g_userdata->size_value = g_fixture.image.size();
	g_userdata->writable_value = false;
	g_userdata->content_value = "Microsoft Basic Data";
	g_userdata->open_value = true;
	gta4l_test.verify_image_bytes[0] = g_fixture.os_size;
	gta4l_test.verify_image_bytes[1] = g_fixture.systemos_size;
	gta4l_test.verify_table_bytes[0] = g_fixture.os_table_bytes;
	gta4l_test.verify_table_bytes[1] = g_fixture.systemos_table_bytes;
	reset_hooks();
	return 0;
}

static int
parse_manifest(void)
{
	memset(&g_manifest, 0, sizeof(g_manifest));
	if (!gta4l_emmc_block_windows_parse(g_fixture.image.data(),
	    GTA4L_EMMC_BLOCK_WINDOWS_MANIFEST_BYTES,
	    g_fixture.image.size(), &g_manifest)) {
		printf("  manifest parse failed: %s\n", gta4l_test.panic);
		return 1;
	}
	return 0;
}

static int
prepare_verify(const char *arguments)
{
	if (begin(arguments) != 0) {
		return 1;
	}
	if (attach_userdata() != 0) {
		return 1;
	}
	return parse_manifest();
}

static int
run_verify(void)
{
	return g_self->runVerify(g_userdata, &g_manifest) ? 0 : 1;
}

static int
open_windows(void)
{
	g_window_os = new Gta4lEmmcBlock();
	g_window_systemos = new Gta4lEmmcBlock();
	if (!g_window_os->configureWindow(g_self, "OS", g_fixture.os_offset,
	    g_fixture.os_size) || !g_window_os->startWindow(g_self)) {
		return 1;
	}
	if (!g_window_systemos->configureWindow(g_self, "SystemOS",
	    g_fixture.systemos_offset, g_fixture.systemos_size) ||
	    !g_window_systemos->startWindow(g_self)) {
		return 1;
	}
	return 0;
}

static int
window_read(Gta4lEmmcBlock *window, uint64_t block, uint64_t nblks,
    int direction, uint8_t *data, IOReturn *returned, IOReturn *completed,
    IOByteCount *actual)
{
	IOMemoryDescriptor *descriptor;
	IOStorageCompletion completion;
	IOReturn result;

	memset(&g_completion, 0, sizeof(g_completion));
	descriptor = IOMemoryDescriptor::withAddress(data,
	    nblks * GTA4L_EMMC_BLOCK_BYTES, direction);
	if (descriptor == nullptr) {
		return 1;
	}
	completion.target = &g_completion;
	completion.action = completion_action;
	completion.parameter = nullptr;
	result = window->doAsyncReadWrite(descriptor, block, nblks, nullptr,
	    &completion);
	descriptor->release();
	*returned = result;
	*completed = g_completion.status;
	*actual = g_completion.actual;
	return 0;
}

static int
expect_read(Gta4lEmmcBlock *window, uint64_t block, uint64_t nblks,
    uint64_t absolute)
{
	uint8_t buffer[64u * GTA4L_EMMC_BLOCK_BYTES];
	IOReturn returned = kIOReturnError;
	IOReturn completed = kIOReturnError;
	IOByteCount actual = 0;

	memset(buffer, 0xa5, sizeof(buffer));
	if (window_read(window, block, nblks, kIODirectionIn, buffer, &returned,
	    &completed, &actual) != 0) {
		return 1;
	}
	if ((returned != kIOReturnSuccess) ||
	    (completed != kIOReturnSuccess) ||
	    (actual != nblks * GTA4L_EMMC_BLOCK_BYTES)) {
		printf("  read returned=%d completed=%d actual=%llu\n",
		    (int)returned, (int)completed,
		    (unsigned long long)actual);
		return 1;
	}
	if (memcmp(buffer, g_fixture.image.data() + absolute,
	    nblks * GTA4L_EMMC_BLOCK_BYTES) != 0) {
		printf("  read data mismatch at %llu\n",
		    (unsigned long long)absolute);
		return 1;
	}
	return 0;
}

static int
scenario_load_and_read(void)
{
	uint64_t last_block = g_fixture.os_size / GTA4L_EMMC_BLOCK_BYTES - 1u;

	CHECK(prepare_verify("gta4l-emmc-block=3 gta4l-emmc-windows=1 "
	    "gta4l-emmc-verify=1") == 0);
	CHECK(run_verify() == 0);
	CHECK(g_self->report.verify == 1u);
	CHECK(g_self->report.verify_valid == 1u);
	CHECK(g_self->report.verify_reason == 0u);
	CHECK(g_self->report.verify_os == 1u);
	CHECK(g_self->report.verify_systemos == 1u);
	CHECK(gta4l_verified_window[0].ready == 1u);
	CHECK(gta4l_verified_window[1].ready == 1u);
	CHECK(open_windows() == 0);
	CHECK(expect_read(g_window_os, 0u, 8u, g_fixture.os_offset) == 0);
	CHECK(expect_read(g_window_os, 1u, 1u,
	    g_fixture.os_offset + GTA4L_EMMC_BLOCK_BYTES) == 0);
	CHECK(expect_read(g_window_os, 7u, 2u,
	    g_fixture.os_offset + 7u * GTA4L_EMMC_BLOCK_BYTES) == 0);
	CHECK(expect_read(g_window_os, last_block, 1u,
	    g_fixture.os_offset + last_block * GTA4L_EMMC_BLOCK_BYTES) == 0);
	CHECK(expect_read(g_window_systemos, 0u, 8u,
	    g_fixture.systemos_offset) == 0);
	return 0;
}

