static int
scenario_read_tamper(void)
{
	uint8_t buffer[GTA4L_EMMC_BLOCK_BYTES];
	IOReturn returned = kIOReturnError;
	IOReturn completed = kIOReturnError;
	IOByteCount actual = 0;
	uint8_t digest[48];
	dev_t device = 0;
	char path[64];
	uint32_t calls;

	CHECK(prepare_verify("gta4l-emmc-block=3 gta4l-emmc-windows=1 "
	    "gta4l-emmc-verify=1") == 0);
	CHECK(run_verify() == 0);
	CHECK(open_windows() == 0);
	g_fixture.image[g_fixture.os_offset + 8192u] ^= 1u;
	memset(buffer, 0xa5, sizeof(buffer));
	calls = g_owner_calls;
	CHECK(window_read(g_window_os, 16u, 1u, kIODirectionIn, buffer,
	    &returned, &completed, &actual) == 0);
	CHECK(returned == kIOReturnSuccess);
	CHECK(completed == kIOReturnNotPermitted);
	CHECK(g_owner_calls == calls + 1u);
	CHECK(buffer[0] == 0xa5u && buffer[sizeof(buffer) - 1u] == 0xa5u);
	CHECK(gta4l_verified_window[0].ready == 0u);
	CHECK(g_window_os->online == false);
	CHECK(window_read(g_window_os, 0u, 1u, kIODirectionIn, buffer,
	    &returned, &completed, &actual) == 0);
	CHECK(completed == kIOReturnNoMedia);
	CHECK(native_verified_block_root_authorized(device) == 0);
	CHECK(native_verified_block_volume_device(
	    "04769D26-2CA0-4825-B443-E2E5F88300F2", &device, path,
	    sizeof(path)) == 0);
	CHECK(native_verified_block_manifest_sha384(device,
	    "04769D26-2CA0-4825-B443-E2E5F88300F2", digest) == 0);
	g_fixture.image = g_fixture.original;
	return 0;
}

static int
scenario_write_refused(void)
{
	uint8_t buffer[GTA4L_EMMC_BLOCK_BYTES];
	IOReturn returned = kIOReturnError;
	IOReturn completed = kIOReturnError;
	IOByteCount actual = 0;
	uint32_t calls;

	CHECK(prepare_verify("gta4l-emmc-block=3 gta4l-emmc-windows=1 "
	    "gta4l-emmc-verify=1") == 0);
	CHECK(run_verify() == 0);
	CHECK(open_windows() == 0);
	calls = g_owner_calls;
	CHECK(window_read(g_window_os, 0u, 1u, kIODirectionOut, buffer,
	    &returned, &completed, &actual) == 0);
	CHECK(returned == kIOReturnNotWritable);
	CHECK(g_completion.calls == 0);
	CHECK(g_owner_calls == calls);
	CHECK(window_read(g_window_os, 0u, 1u, 0, buffer, &returned,
	    &completed, &actual) == 0);
	CHECK(returned == kIOReturnBadArgument);
	CHECK(g_owner_calls == calls);
	return 0;
}

