static int
scenario_bench(void)
{
	static uint8_t buffer[32u * GTA4L_EMMC_BLOCK_BYTES];
	struct timespec start;
	struct timespec end;
	uint64_t bytes = 0;
	uint64_t spans = 0;
	uint64_t elapsedUs;
	uint64_t index;

	CHECK(prepare_verify("gta4l-emmc-block=3 gta4l-emmc-windows=1 "
	    "gta4l-emmc-verify=1") == 0);
	CHECK(run_verify() == 0);
	CHECK(open_windows() == 0);
	CHECK(clock_gettime(CLOCK_MONOTONIC, &start) == 0);
	for (index = 0; index < 64u; index++) {
		uint8_t *target = buffer;
		IOReturn returned = kIOReturnError;
		IOReturn completed = kIOReturnError;
		IOByteCount actual = 0;

		CHECK(window_read(g_window_os, index * 32u, 32u,
		    kIODirectionIn, target, &returned, &completed,
		    &actual) == 0);
		CHECK(completed == kIOReturnSuccess);
		CHECK(actual == sizeof(buffer));
		bytes += sizeof(buffer);
		spans += 8u;
	}
	CHECK(clock_gettime(CLOCK_MONOTONIC, &end) == 0);
	elapsedUs = (uint64_t)(end.tv_sec - start.tv_sec) * 1000000ull +
	    (uint64_t)(end.tv_nsec - start.tv_nsec) / 1000ull;
	if (elapsedUs == 0u) {
		elapsedUs = 1u;
	}
	printf("  BENCH: bytes=%llu spans=%llu us=%llu spans_per_s=%llu\n",
	    (unsigned long long)bytes, (unsigned long long)spans,
	    (unsigned long long)elapsedUs,
	    (unsigned long long)((spans * 1000000ull) / elapsedUs));
	return 0;
}

